mapper.select:
select o.*,g.name goodName ,s.name storeName from tb_orders o left join tb_goods g on o.good_id=g.id left join tb_store s on o.store_id=s.id where 1=1
and o.order_no like concat('%',#{orderId},'%')
and g.name like concat('%',#{goodsName},'%')
and o.state =#{orderStatus}
and o.store_Id =#{storeId}
